// 모든 응답이 여기를 지난다: 응답 본문은 그대로 두고, /logs에 남길 한 줄을 만든다.
// 남기는 것: request_id, route, intents, 하위 웹훅별 시간(steps), llm_calls, ticket 여부, blocked_by (+ 77 보고서가 읽는 status, duration_ms, started_at, tag)
// 남기지 않는 것: 질문 원문, 답변, 사용자 이름, 연락처
const tryJson = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const body = (tryJson('Question webhook') || {}).body || {};
const plan = tryJson('Plan route');
const started = (tryJson('Check input') || {}).started_at ?? null;
const now = Date.now();
const invalid = $json.valid === false;
const response = invalid ? $json.error : $json;
const res = invalid
  ? { route: null, sources: [], ticket: null, security: { blocked_by: '', masked: 0 }, timings: {} }
  : response;
const { total_ms, ...steps } = res.timings || {};
const agents = res.agents || {};
const errMsg = [agents.error, agents.search_error, (agents.handoff || {}).error].find(Boolean) || null;
const kst = (t) => new Date(t + 9 * 3600000).toISOString().slice(0, 19); // 데이터 API와 같은 한국 시간 형식
const log = {
  workflow: 'ticketmoa-support',
  execution_id: Number($execution.id),
  ...buildLog(body, res, { intents: plan ? plan.intents : [], started_at: kst(started ?? now) }),
  status: invalid ? 'rejected' : (/_failed$/.test(String(res.reason || '')) || errMsg ? 'error' : 'success'),
  error_message: errMsg ? String(errMsg).slice(0, 120) : null,
  codes: invalid ? $json.codes : undefined,
  duration_ms: started ? now - started : null,
  steps,
  llm_calls: agents.llm_calls ?? 0,
  has_ticket: Boolean(res.ticket),
  tag: typeof body.tag === 'string' ? body.tag : '',
};
return [{ json: { log, response, status_code: invalid ? 400 : 200 } }];

// ↓ lib/common.js에서 그대로 복사 (고치려면 lib/common.js를 고치고 다시 복사)
const ROUTES = {
  AUTO: '자동 답변',
  CLARIFY: '보완 질문',
  HANDOFF: '담당자 이관',
  FORBIDDEN: '권한 없음',
  BLOCKED: '차단',
};
// ↑ lib/common.js 복사 끝

// 검색이 실패해도 이관은 그대로 간다 (근거만 빠진다)
const plan = $('Plan route').first().json;
const r = $json || {};
const hits = !r.error && Array.isArray(r.hits) ? r.hits : [];
return [{ json: { route: ROUTES.HANDOFF, answer: plan.evidence.answer, sources: hits, needs_handoff: true,
  reason: plan.reason, masked: 0, used: [...plan.used, 'ticketmoa-search'], llm_calls: plan.llm_calls,
  agents_extra: r.error ? { search_error: String(r.error.message || r.error).slice(0, 200) } : {},
  steps: { ...plan.steps, search_ms: Date.now() - plan.t_routed } } }];
